with
t as (select 'tables_rls' k, string_agg(c.relname||':'||c.relrowsecurity::text||':'||c.relkind::text, '|' order by c.relname) v, count(*) n from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','v','p','m')),
cols as (select 'columns', string_agg(table_name||'.'||column_name||':'||data_type||':'||is_nullable, '|' order by table_name,column_name), count(*) from information_schema.columns where table_schema='public'),
defs as (select 'column_defaults', string_agg(table_name||'.'||column_name||'='||coalesce(regexp_replace(column_default,'\s+','','g'),''), '|' order by table_name,column_name), count(*) from information_schema.columns where table_schema='public' and column_default is not null),
fn as (select 'functions', string_agg(p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||p.prosecdef::text||':'||p.provolatile::text||':'||coalesce(p.proconfig::text,'')||':'||md5(regexp_replace(p.prosrc,'\s+','','g')), '|' order by p.proname, pg_get_function_identity_arguments(p.oid)), count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname<>'rls_auto_enable'),
fnpriv as (select 'function_privileges', string_agg(p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||has_function_privilege('anon',p.oid,'execute')::text||has_function_privilege('authenticated',p.oid,'execute')::text||has_function_privilege('service_role',p.oid,'execute')::text, '|' order by p.proname, pg_get_function_identity_arguments(p.oid)), count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname<>'rls_auto_enable'),
pol as (select 'policies', string_agg(schemaname||'.'||tablename||':'||policyname||':'||cmd||':'||array_to_string(roles,',')||':'||coalesce(regexp_replace(qual,'\s+','','g'),'')||':'||coalesce(regexp_replace(with_check,'\s+','','g'),''), '|' order by schemaname,tablename,policyname), count(*) from pg_policies where schemaname='public' or (schemaname='storage' and tablename='objects' and policyname not like 'Allow%')),
trg as (select 'triggers', string_agg(c.relname||':'||t.tgname||':'||t.tgenabled::text, '|' order by c.relname,t.tgname), count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname='public' or (n.nspname='auth' and c.relname='users'))),
con as (select 'constraints', string_agg(c.conrelid::regclass::text||':'||c.conname||':'||regexp_replace(pg_get_constraintdef(c.oid),'\s+','','g'), '|' order by c.conrelid::regclass::text,c.conname), count(*) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public'),
idx as (select 'indexes', string_agg(tablename||':'||indexname, '|' order by tablename,indexname), count(*) from pg_indexes where schemaname='public'),
tpriv as (select 'table_privileges', string_agg(table_name||':'||grantee||':'||privilege_type, '|' order by table_name,grantee,privilege_type), count(*) from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role')),
cpriv as (select 'column_privileges', string_agg(table_name||'.'||column_name||':'||grantee||':'||privilege_type, '|' order by table_name,column_name,grantee,privilege_type), count(*) from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated')),
bkt as (select 'buckets', string_agg(id||':'||public::text||':'||coalesce(file_size_limit::text,'')||':'||coalesce(allowed_mime_types::text,''), '|' order by id), count(*) from storage.buckets)
select k, n, md5(v) h from (select * from t union all select * from cols union all select * from defs union all select * from fn union all select * from fnpriv union all select * from pol union all select * from trg union all select * from con union all select * from idx union all select * from tpriv union all select * from cpriv union all select * from bkt) x order by k;
